-- vi: 96 concepts, in course order.
on conflict (language_code, slug) do update
set
  kind = excluded.kind,
  canonical_form = excluded.canonical_form,
  gloss = excluded.gloss,
  description = coalesce(nullif(excluded.description, excluded.gloss), public.concepts.description, excluded.description),
  metadata = public.concepts.metadata || excluded.metadata,
  sort_order = excluded.sort_order,
  is_active = true,
  updated_at = now();
